module tb_TopModule;
    logic       clk;
    logic       reset;
    logic [7:0] d;
    logic [7:0] q;

    TopModule dut (
        .clk(clk),
        .reset(reset),
        .d(d),
        .q(q)
    );

    initial begin
        clk = 0;
        forever #5 clk = ~clk;
    end

    initial begin
        reset = 1;
        d = 8'hA5;
        @(negedge clk);
        #1;
        if (q !== 8'h34) begin
            $display("SELFTEST FAIL: Reset value incorrect. Expected 0x34, got %h", q);
            $finish;
        end

        reset = 0;
        d = 8'h5A;
        @(negedge clk);
        #1;
        if (q !== 8'h5A) begin
            $display("SELFTEST FAIL: Data capture incorrect. Expected 0x5A, got %h", q);
            $finish;
        end

        d = 8'h12;
        @(negedge clk);
        #1;
        if (q !== 8'h12) begin
            $display("SELFTEST FAIL: Data capture incorrect. Expected 0x12, got %h", q);
            $finish;
        end

        // Test synchronous reset again
        reset = 1;
        d = 8'hFF;
        @(negedge clk);
        #1;
        if (q !== 8'h34) begin
            $display("SELFTEST FAIL: Synchronous reset during operation incorrect. Expected 0x34, got %h", q);
            $finish;
        end

        $display("SELFTEST PASS");
        $finish;
    end
endmodule
